def isValid(word: str) -> bool:
    # Condition 1: Minimum of 3 characters
    if len(word) < 3:
        return False

    vowels = set("aeiouAEIOU")
    has_vowel = False
    has_consonant = False

    for char in word:
        # Condition 2: Only digits and English letters
        if not (char.isalnum()):
            return False

        if char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                has_consonant = True

    # Condition 3 & 4: At least one vowel and at least one consonant
    return has_vowel and has_consonant
