def latestTime(s: str) -> str:
    # Convert string to a list for easy modification
    res = list(s)

    # Handle HH (Hour) part
    # For the first digit (res[0]):
    # If it's '?', it can be '1' if the second digit is '0', '1', or '?'
    # Otherwise, if the second digit is '2'-'9', the first digit must be '0'.
    if res[0] == '?':
        if res[1] == '?' or res[1] == '0' or res[1] == '1':
            res[0] = '1'
        else:
            res[0] = '0'

    # For the second digit (res[1]):
    # If first digit is '0', max is '9'.
    # If first digit is '1', max is '1'.
    if res[1] == '?':
        if res[0] == '0':
            res[1] = '9'
        else:
            res[1] = '1'

    # Handle MM (Minute) part
    # For the third digit (res[3]):
    # Max possible for the tens place of minutes is '5'.
    if res[3] == '?':
        res[3] = '5'

    # For the fourth digit (res[4]):
    # Max possible for the units place of minutes is '9'.
    if res[4] == '?':
        res[4] = '9'

    return "".join(res)
