def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    cuboids = []
    idx = 1
    for i in range(N):
        x1 = int(input_data[idx])
        y1 = int(input_data[idx+1])
        z1 = int(input_data[idx+2])
        x2 = int(input_data[idx+3])
        y2 = int(input_data[idx+4])
        z2 = int(input_data[idx+5])
        # Ensure coordinates are sorted (though constraints say X1 < X2)
        cuboids.append((min(x1, x2), min(y1, y2), min(z1, z2), 
                        max(x1, x2), max(y1, y2), max(z1, z2)))
        idx += 6

    # Since the coordinate range is small (0-100), we can use a 3D grid.
    # However, the problem asks for positive AREA of intersection.
    # A face is shared if two cuboids meet at a plane and their 2D projections overlap.
    # We can represent the space as cells of size 1x1x1.
    # But a cuboid's face is on the boundary between cells.
    # Let's use a grid where grid[x][y][z] stores the index of the cuboid occupying that cell.
    # Max coordinate is 100, so 100x100x100 is 10^6, which fits in memory.

    grid = [[[ -1 for _ in range(100)] for _ in range(100)] for _ in range(100)]

    for i in range(N):
        x1, y1, z1, x2, y2, z2 = cuboids[i]
        for x in range(x1, x2):
            for y in range(y1, y2):
                for z in range(z1, z2):
                    grid[x][y][z] = i

    adj = [set() for _ in range(N)]

    # Check neighbors in X direction
    for x in range(99):
        for y in range(100):
            for z in range(100):
                u = grid[x][y][z]
                v = grid[x+1][y][z]
                if u != -1 and v != -1 and u != v:
                    adj[u].add(v)
                    adj[v].add(u)

    # Check neighbors in Y direction
    for x in range(100):
        for y in range(99):
            for z in range(100):
                u = grid[x][y][z]
                v = grid[x][y+1][z]
                if u != -1 and v != -1 and u != v:
                    adj[u].add(v)
                    adj[v].add(u)

    # Check neighbors in Z direction
    for x in range(100):
        for y in range(100):
            for z in range(99):
                u = grid[x][y][z]
                v = grid[x][y][z+1]
