import sys

def rotate_90(shape):
    """Rotates a 4x4 grid 90 degrees clockwise."""
    new_shape = [['.' for _ in range(4)] for _ in range(4)]
    for r in range(4):
        for c in range(4):
            new_shape[c][3-r] = shape[r][c]
    return new_shape

def get_all_rotations(shape):
    """Returns all 4 rotations of a polyomino."""
    rots = []
    curr = shape
    for _ in range(4):
        rots.append(curr)
        curr = rotate_90(curr)
    return rots

def get_relative_coords(shape):
    """Converts # positions to relative coordinates based on the first # found."""
    coords = []
    for r in range(4):
        for c in range(4):
            if shape[r][c] == '#':
                coords.append((r, c))
    if not coords:
        return []
    min_r, min_c = coords[0]
    return [(r - min_r, c - min_c) for r, c in coords]

def solve():
    # Read 12 lines of input
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    # Parse the 3 polyominoes
    polyominoes_raw = []
    for i in range(0, 12, 4):
        grid = [list(line) for line in input_data[i:i+4]]
        polyominoes_raw.append(grid)

    # For each polyomino, find all possible relative coordinates for all 4 rotations
    all_variants = []
    for poly in polyominoes_raw:
        variants = []
        for rot in get_all_rotations(poly):
            # Normalize to the first '#' found to make translation easier
            coords = []
            for r in range(4):
                for c in range(4):
                    if rot[r][c] == '#':
                        coords.append((r, c))

            # To avoid duplicate rotations of the same shape, we normalize to (0,0)
            # and store the set of relative coordinates.
            if coords:
                # We shift so the top-left-most # is at (0,0)
                min_r = min(r for r, c in coords)
                min_c = min(c for r, c in coords if r == min_r)
                normalized = sorted([(r - min_r, c - min_c) for r, c in coords])
                variants.append(normalized)

        # Remove duplicate rotations
        unique_variants = []
        for v in variants:
            if v not in unique_variants:
                unique_variants.append(v)
        all_variants.append(unique_variants)

    # Total squares must be exactly 16
    total_squares = sum(len(all_variants[0][0]), len(all_variants[1][0]), len(all_variants[2][0]))
    if total_squares != 16:
        print("No")
        return

    # Backtracking to place polyominoes
    grid = [[False for _ in range(4)] for _ in range(4)]

    def can_place(variant, start_r, start_c):
        for dr, dc in variant:
            nr, nc = start_r + dr, start_c + dc
            if not (0 <= nr < 4 and 0 <= nc < 4) or grid[nr][nc]:
                return False
        return True

    def place(variant, start_r, start_c, val):
        for dr, dc in variant:
            grid[start_r + dr][start_c + dc] = val

    def backtrack(poly_idx):
        if poly_idx == 3:
            return True

        # Try every rotation variant of the current polyomino
        for variant in all_variants[poly_idx]:
            # Try every possible top-left position (relative to the normalized 0,0)
            # Note: since normalized is relative to the first #, we check all grid cells
            for r in range(4):
                for c in range(4):
                    if can_place(variant, r, c):
                        place(variant, r, c, True)
                        if backtrack(poly_idx + 1):
                            return True
                        place(variant, r, c, False)
        return False

    if backtrack(0):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

