import sys

def solve():
    # Read the 3x3 grid from stdin
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        A = [int(x) for x in input_data]
    except EOFError:
        return

    # The game is a 3x3 grid game. 
    # The winning conditions are:
    # 1. Getting 3 in a row (standard Tic-Tac-Toe win).
    # 2. If no one gets 3 in a row, the person with the higher sum of values wins.

    # Since the total sum is odd, there are no draws based on score.
    # The state space for a 3x3 grid is small enough to solve using minimax with memoization.
    # State: (tuple of cell colors, current player)
    # Colors: 0 = white, 1 = Takahashi (Red), 2 = Aoki (Blue)

    memo = {}

    # Winning lines for Tic-Tac-Toe
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8), # rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8), # cols
        (0, 4, 8), (2, 4, 6)            # diags
    ]

    def check_win(board, color):
        for line in lines:
            if board[line[0]] == board[line[1]] == board[line[2]] == color:
                return True
        return False

    def get_score(board):
        t_score = 0
        a_score = 0
        for i in range(9):
            if board[i] == 1:
                t_score += A[i]
            elif board[i] == 2:
                a_score += A[i]
        return t_score, a_score

    def minimax(board, turn):
        state = (board, turn)
        if state in memo:
            return memo[state]

        # Turn: 1 for Takahashi, 2 for Aoki
        # Check if previous player won by 3-in-a-row
        prev_player = 2 if turn == 1 else 1
        if check_win(board, prev_player):
            # Previous player won, so current player loses
            return prev_player == 1 # True if Takahashi wins, False if Aoki wins

        # Check if board is full
        if 0 not in board:
            ts, as_ = get_score(board)
            return ts > as_

        # Try all possible moves
        possible_moves = [i for i, val in enumerate(board) if val == 0]

        if turn == 1: # Takahashi's turn (maximize chance of winning)
            res = False
            for move in possible_moves:
                new_board = list(board)
                new_board[move] = 1
                if minimax(tuple(new_board), 2):
                    res = True
                    break
            memo[state] = res
            return res
        else: # Aoki's turn (minimize chance of Takahashi winning)
            res = True
            for move in possible_moves:
                new_board = list(board)
                new_board[move] = 2
                if not minimax(tuple(new_board), 1):
                    res = False
                    break
            memo[state] = res
            return res

    initial_board = tuple([0] * 9)
    if minimax(initial_board, 1):
        print("Takahashi")
    else:
        print("Aoki")

if __name__ == "__main__":
    solve()

```

