def solve(s: str, k: int) -> int:
    n = len(s)

    # Precompute the cost to make a substring s[i:j] a semi-palindrome
    # cost[i][j] stores the minimum changes for substring from index i to j-1
    cost = [[float('inf')] * (n + 1) for _ in range(n)]

    def get_semi_palindrome_cost(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_changes = float('inf')
        # Try all possible divisors d such that 1 <= d < m and m % d == 0
        for d in range(1, m):
            if m % d == 0:
                current_changes = 0
                # For each group starting at offset r, indices are r, r+d, r+2d...
                # This sequence must be a palindrome
                for r in range(d):
                    # Extract characters at indices r, r+d, r+2d...
                    group = [sub[i] for i in range(r, m, d)]
                    # Calculate changes to make this specific group a palindrome
                    g_len = len(group)
                    for i in range(g_len // 2):
                        if group[i] != group[g_len - 1 - i]:
                            current_changes += 1
                min_changes = min(min_changes, current_changes)
        return min_changes

    # Fill the cost table for all possible substrings
    for i in range(n):
        for j in range(i + 2, n + 1):
            cost[i][j] = get_semi_palindrome_cost(s[i:j])

    # DP state: dp[i][j] is the min cost to partition s[0:j] into i substrings
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        # The current partition must have at least 2 characters per substring
        # So j must be at least 2 * i
        for j in range(2 * i, n + 1):
            # Try splitting the string at index p
            # The last substring is s[p:j], which must be a semi-palindrome
            for p in range(2 * (i - 1), j - 1):
                if dp[i-1][p] != float('inf') and cost[p][j] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i-1][p] + cost[p][j])

    return int(dp[k][n])
```

