def solve(wordsContainer, wordsQuery):
    # A Trie will store the reversed strings to handle suffixes as prefixes
    # Each node in the Trie will store the index of the "best" word that passes through it.
    # "Best" is defined by: smallest length, then smallest index.
    trie = {}

    # To keep track of the best index for each node
    # node_best[node] = (length, index)
    node_best = {}

    for i, word in enumerate(wordsContainer):
        curr = trie
        # Reverse the word to treat suffix as prefix
        rev_word = word[::-1]
        word_len = len(word)

        # Traverse/Build the Trie
        for char in rev_word:
            if char not in curr:
                curr[char] = {}
            curr = curr[char]

            # Update the best word index for this prefix (suffix of original word)
            # We store (length, index) to easily compare
            node_id = id(curr)
            if node_id not in node_best or (word_len, i) < node_best[node_id]:
                node_best[node_id] = (word_len, i)

    # For the case where no common suffix exists (empty suffix), 
    # we need the best word from the entire container.
    global_best_idx = 0
    min_len = len(wordsContainer[0])
    for i in range(1, len(wordsContainer)):
        if len(wordsContainer[i]) < min_len:
            min_len = len(wordsContainer[i])
            global_best_idx = i

    ans = []
    for query in wordsQuery:
        curr = trie
        rev_query = query[::-1]
        last_best_idx = global_best_idx

        for char in rev_query:
            if char in curr:
                curr = curr[char]
                last_best_idx = node_best[id(curr)][1]
            else:
                break
        ans.append(last_best_idx)

    return ans
