import sys

def solve():
    # Read all input at once for efficiency
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    T_prime = input_data[1]
    len_tp = len(T_prime)

    results = []

    # The strings S_i start from index 2 in input_data
    for i in range(N):
        S = input_data[i + 2]
        len_s = len(S)

        # Condition 1: T' is equal to T (S)
        if len_s == len_tp:
            # Check if they are identical or differ by exactly one character
            diff_count = 0
            possible = False
            if S == T_prime:
                possible = True
            else:
                # Check if they differ by exactly one character (Condition 4)
                # We can iterate and count mismatches
                mismatches = 0
                for char_s, char_tp in zip(S, T_prime):
                    if char_s != char_tp:
                        mismatches += 1
                        if mismatches > 1:
                            break
                if mismatches == 1:
                    possible = True

            if possible:
                results.append(i + 1)

        elif len_s == len_tp - 1:
            # Condition 2: T' is obtained by inserting one char into T (S)
            # This means S is T' with one character removed.
            # We check if S is a subsequence of T' with length len_tp - 1.
            it = iter(T_prime)
            if all(char in it for char in S):
                results.append(i + 1)

