import math
from itertools import combinations

def kthSmallestAmount(coins, k):
    # Inclusion-Exclusion Principle helper to count multiples of at least one coin up to 'mid'
    def count_multiples(mid):
        total = 0
        n = len(coins)
        # Iterate through all non-empty subsets of coins
        for i in range(1, 1 << n):
            lcm_val = 1
            bits = 0
            for j in range(n):
                if (i >> j) & 1:
                    bits += 1
                    lcm_val = (lcm_val * coins[j]) // math.gcd(lcm_val, coins[j])
                    if lcm_val > mid:
                        break

            if lcm_val <= mid:
                if bits % 2 == 1:
                    total += mid // lcm_val
                else:
                    total -= mid // lcm_val
        return total

    # Binary search for the smallest value 'mid' such that count_multiples(mid) >= k
    low = 1
    high = min(coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_multiples(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
