import sys

def solve():
    # Read all input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    adj = [[0] * N for _ in range(N)]

    # The input format provides weights for i < j
    # D_{1,2}, D_{1,3}... D_{1,N}
    # D_{2,3}... D_{2,N}
    # ...
    idx = 1
    for i in range(N - 1):
        for j in range(i + 1, N):
            weight = int(input_data[idx])
            adj[i][j] = adj[j][i] = weight
            idx += 1

    # DP state: dp[mask] is the max weight using vertices in the mask
    # Since N is small (up to 16), we can use bitmask DP.
    dp = [-1] * (1 << N)
    dp[0] = 0

    for mask in range(1 << N):
        if dp[mask] == -1:
            continue

        # Find the first vertex not in the mask to avoid redundant permutations
        first = -1
        for i in range(N):
            if not (mask & (1 << i)):
                first = i
                break

        if first == -1:
            continue

        # Option 1: Skip the 'first' vertex (it won't be part of any chosen edge)
        new_mask_skip = mask | (1 << first)
        if dp[new_mask_skip] < dp[mask]:
            dp[new_mask_skip] = dp[mask]

        # Option 2: Pair 'first' vertex with another available vertex 'j'
        for j in range(first + 1, N):
            if not (mask & (1 << j)):
                new_mask_pair = mask | (1 << first) | (1 << j)
                new_weight = dp[mask] + adj[first][j]
                if dp[new_mask_pair] < new_weight:
                    dp[new_mask_pair] = new_weight

    print(dp[(1 << N) - 1])

if __name__ == "__main__":
    solve()
