import sys
from collections import deque

def solve():
    # Read H, W, T
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        H, W, T = map(int, line1)
    except ValueError:
        return

    grid = [sys.stdin.readline().strip() for _ in range(H)]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'G':
                goal_pos = (r, c)
            elif grid[r][c] == 'o':
                candies.append((r, c))

    # All points of interest: Start, Candies, Goal
    poi = [start_pos] + candies + [goal_pos]
    num_poi = len(poi)
    num_candies = len(candies)

    # Distance matrix between all POIs
    dist_matrix = [[float('inf')] * num_poi for _ in range(num_poi)]

    def bfs(start_node_idx):
        sr, sc = poi[start_node_idx]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for i in range(num_poi):
            pr, pc = poi[i]
            if dists[pr][pc] != -1:
                dist_matrix[start_node_idx][i] = dists[pr][pc]

    for i in range(num_poi):
        bfs(i)

    # DP state: dp[mask][i] = minimum time to visit set of candies 'mask' and end at poi 'i'
    # mask is a bitmask of length num_candies. 
    # i is index in poi (0: start, 1..num_candies: candies, num_poi-1: goal)
    # However, we only need to track the last visited candy.

    # dp[mask][i] where i is index of the candy (0 to num_candies-1)
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Initialize: distance from start to each candy
    for i in range(num_candies):
        d = dist_matrix[0][i + 1]
        if d <= T:
            dp[1 << i][i] = d

    # Transition
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] > T:
                continue
            # Try moving to another candy not in mask
            for j in range(num_candies):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    new_dist = dp[mask][i] + dist_matrix[i + 1][j + 1]
                    if new_dist < dp[new_mask][j]:
                        dp[new_mask][j] = new_dist

    # Final check: reach goal from any state
    max_candies = -1

    # Check if start can reach goal directly
    if dist_matrix[0][num_poi - 1] <= T:
        max_candies = 0

    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] > T:
                continue
            # distance from candy i to goal
            total_dist = dp[mask][i] + dist_matrix[i + 1][num_poi - 1]
            if total_dist <= T:
                # Count bits in mask
                count = bin(mask).count('1')
                if count > max_candies:
                    max_candies = count

    print(max_candies)

if __name__ == "__main__":
    solve()
