def longestCommonPrefix(arr1, arr2):
    prefixes1 = set()
    for num in arr1:
        s = str(num)
        # Store all possible prefixes of each number in arr1
        for i in range(1, len(s) + 1):
            prefixes1.add(s[:i])

    max_len = 0
    for num in arr2:
        s = str(num)
        # Check all possible prefixes of each number in arr2
        # We iterate backwards from longest to shortest to optimize
        for i in range(len(s), 0, -1):
            if i <= max_len:
                break
            if s[:i] in prefixes1:
                max_len = i
                break

    return max_len
