import heapq

def minCostToConvert(source, target, original, changed, cost):
    # Initialize a distance matrix for all lowercase English letters (26x26)
    # Using float('inf') to represent unreachable paths
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # Distance from a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Populate the initial graph with the given conversion costs
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        if w < dist[u][v]:
            dist[u][v] = w

    # Use Floyd-Warshall algorithm to find the shortest path between all pairs of characters
    # Since there are only 26 characters, O(26^3) is very efficient
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] != inf and dist[k][j] != inf:
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    # Calculate the total cost to transform source to target
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u = ord(s_char) - ord('a')
        v = ord(t_char) - ord('a')

        # If there is no path from s_char to t_char, it's impossible
        if dist[u][v] == inf:
            return -1

        total_cost += dist[u][v]

    return total_cost
