    min_ops = float('inf')

    # Check horizontal segments
    if W >= K:
        for i in range(H):
            row = grid[i]
            # We use a sliding window to count 'x' and '.' in segments of length K
            x_count = 0
            dot_count = 0
            # Initial window
            for j in range(K):
                if row[j] == 'x':
                    x_count += 1
                elif row[j] == '.':
                    dot_count += 1

            if x_count == 0:
                min_ops = min(min_ops, dot_count)

            # Slide the window
            for j in range(1, W - K + 1):
                # Remove leftmost character of previous window
                prev_char = row[j-1]
                if prev_char == 'x':
                    x_count -= 1
                elif prev_char == '.':
                    dot_count -= 1

                # Add rightmost character of current window
                next_char = row[j + K - 1]
                if next_char == 'x':
                    x_count += 1
                elif next_char == '.':
                    dot_count += 1

                if x_count == 0:
                    min_ops = min(min_ops, dot_count)

    # Check vertical segments
    if H >= K:
        for j in range(W):
            # Extract column as a list/string
            col = [grid[i][j] for i in range(H)]
            x_count = 0
            dot_count = 0
            # Initial window
            for i in range(K):
                if col[i] == 'x':
                    x_count += 1
                elif col[i] == '.':
                    dot_count += 1

            if x_count == 0:
                min_ops = min(min_ops, dot_count)

            # Slide the window
            for i in range(1, H - K + 1):
                # Remove top character of previous window
                prev_char = col[i-1]
                if prev_char == 'x':
                    x_count -= 1
                elif prev_char == '.':
                    dot_count -= 1

                # Add bottom character of current window
                next_char = col[i + K - 1]
                if next_char == 'x':
                    x_count += 1
                elif next_char == '.':
                    dot_count += 1

                if x_count == 0:
                    min_ops = min(min_ops, dot_count)

    if min_ops == float('inf'):
