import math

def canConnectAll(nums):
    if len(nums) == 1:
        return True

    # Union-Find structure to group indices that are connected
    parent = list(range(len(nums)))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the first index in nums that is divisible by it
    prime_to_index = {}

    for i, val in enumerate(nums):
        # Find all prime factors of val
        temp = val
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all indices belong to the same connected component
    root = find(0)
    for i in range(1, len(nums)):
        if find(i) != root:
            return False

    return True
