    all_indices = list(itertools.permutations(range(N), 3))

    # Pre-calculate all possible row strings
    possible_rows = []
    for indices in all_indices:
        row = ['.'] * N
        row[indices[0]] = 'A'
        row[indices[1]] = 'B'
        row[indices[2]] = 'C'
        possible_rows.append("".join(row))

