    S = [input_data[1], input_data[2], input_data[3]]

    min_total_time = float('inf')

    # We want all reels to display the same digit 'd' (0-9)
    for d in range(10):
        char_d = str(d)

        # Find all positions (0-indexed) where digit d appears in each reel
        pos = []
        possible = True
        for i in range(3):
            indices = [j for j in range(M) if S[i][j] == char_d]
            if not indices:
                possible = False
                break
            pos.append(indices)

        if not possible:
            continue

        # Since there are only 3 reels and M is small, we can iterate 
        # through all combinations of indices from the 3 reels.
        # Let the chosen indices be j0, j1, j2.
        # The time taken for reel i is t_i = k_i * M + j_i.
        # We need to find k0, k1, k2 such that t0, t1, t2 are distinct 
        # and max(t0, t1, t2) is minimized.

        for j0 in pos[0]:
            for j1 in pos[1]:
                for j2 in pos[2]:
                    # We need to assign t0, t1, t2 to be distinct.
                    # The possible values for t_i are j_i, j_i + M, j_i + 2M...
                    # Since we have only 3 reels, the optimal t_i will not exceed 
                    # j_i + 2*M because there are only 3 slots to fill.

                    # Try all combinations of k_i in {0, 1, 2}
                    # This is a small search space (3^3 = 27)
                    for k0 in range(3):
                        t0 = k0 * M + j0
                        for k1 in range(3):
                            t1 = k1 * M + j1
                            for k2 in range(3):
                                t2 = k2 * M + j2

                                if t0 != t1 and t1 != t2 and t0 != t2:
                                    current_max = max(t0, t1, t2)
                                    if current_max < min_total_time:
                                        min_total_time = current_max

    if min_total_time == float('inf'):
        print("-1")
    else:
        print(min_total_time)

